window.addEventListener('keydown',e=>{if(['ArrowUp','ArrowDown','ArrowLeft','ArrowRight','Space'].includes(e.code))e.preventDefault();if(e.code==='KeyM'&&!e.repeat){toggleMusic();return;}if(e.code==='Escape'){if(mazeOpen)closeMaze();else if(started&&!paused)pause();return;}const slot={KeyE:0,KeyF:1,KeyG:2}[e.code];if(slot!==undefined&&!e.repeat){interact(slot);return;}if(mazeOpen){const map={ArrowUp:[0,-1],ArrowDown:[0,1],ArrowLeft:[-1,0],ArrowRight:[1,0]};if(map[e.code]&&!e.repeat)moveMaze(...map[e.code]);return;}keys.add(e.code);});window.addEventListener('keyup',e=>keys.delete(e.code));window.addEventListener('blur',()=>{keys.clear();if(started&&!mazeOpen)pause();});
